//! LTC (Linearly Transformed Cosines) lookup tables for rect area lights.
//! Source: three.js r160, examples/jsm/lights/RectAreaLightUniformsLib.js
//! Permalink: https://raw.githubusercontent.com/mrdoob/three.js/r160/examples/jsm/lights/RectAreaLightUniformsLib.js
//! Upstream origin: https://github.com/selfshadow/ltc_code/tree/master/fit/results/ltc.js
//! Paper: "Real-Time Polygonal-Light Shading with Linearly Transformed Cosines"
//!        Eric Heitz, Jonathan Dupuy, Stephen Hill, David Neubelt (SIGGRAPH 2016)
//!
//! Layout: 64x64 texels, RGBA (4 floats per texel), row-major. Total: 64*64*4 = 16384 floats each.
//!
//! LUT UV indexing (MUST match the eval shader exactly):
//!   float dotNV = saturate(dot(N, V));
//!   vec2 uv = vec2(roughness, sqrt(1.0 - dotNV));   // x=roughness, y=sqrt(1-cosTheta)
//!   const float LUT_SIZE  = 64.0;
//!   const float LUT_SCALE = (LUT_SIZE - 1.0) / LUT_SIZE;  // = 63/64
//!   const float LUT_BIAS  = 0.5 / LUT_SIZE;               // = 0.5/64
//!   uv = uv * LUT_SCALE + LUT_BIAS;
//!   // Then sample ltc_mat and ltc_mag at this uv (bilinear, clamp-to-edge).
//!
//! ltc_mat (LTC_MAT_1 / ltc_1) RGBA meaning:
//!   Stores 4 of the 5 non-trivial coefficients of the 3x3 inverse-M matrix Minv.
//!   The matrix Minv has the form (by symmetry of the LTC fit):
//!     | t1.x   0   t1.y |
//!     |   0    1     0  |
//!     | t1.z   0   t1.w |
//!   where t1 = texture sample (R=t1.x, G=t1.y, B=t1.z, A=t1.w).
//!   In GLSL:
//!     vec4 t1 = texture2D(ltc_1, uv);
//!     mat3 mInv = mat3(vec3(t1.x, 0, t1.y), vec3(0, 1, 0), vec3(t1.z, 0, t1.w));
//!
//! ltc_mag (LTC_MAT_2 / ltc_2) RGBA meaning:
//!   R = LTC magnitude/norm (GGX energy normalization factor).
//!   G = Fresnel term (used for the LTC Fresnel approximation by Stephen Hill,
//!       http://blog.selfshadow.com/publications/s2016-advances/s2016_ltc_fresnel.pdf).
//!   In GLSL:
//!     vec4 t2 = texture2D(ltc_2, uv);
//!     vec3 fresnel = material.specularColor * t2.x + (1.0 - material.specularColor) * t2.y;
//!   B, A channels are unused/padding (B=0, A=1 observed).
//!
//! Diffuse rect area: LTC_Evaluate with identity mat3(1.0) (no LUT lookup needed).

pub const lut_size: u32 = 64;

